def ModuleObjectStubs(entries):
    """THE OBJECTS OF THE MODULE - exudyn.config, exudyn.special and its parts, exudyn.experimental -
    as stub classes (#2541). They are declared in definitions/pybindModule.py by dotted names,
    'special.solver.timeout', which the general stub emission cannot place; here an entry whose type
    is a class of its own opens that class, and the dotted entries below it become its members.
    entries: [(call, args, kwargs)] of DefDataAccess and DefPyFunctionAccess, in declaration order"""
    classOf = {}            #'special.solver' -> 'SpecialSolver'
    descriptionOf = {}
    for (call, args, kwargs) in entries:
        if call == 'DefDataAccess':
            name = args[0]
            dataType = kwargs.get('dataType', '')
            if dataType != '' and dataType[0].isupper() and dataType not in ['SystemContainer', 'Any'] \
                    and (name.count('.') == 0 or name.rsplit('.', 1)[0] in classOf):
                classOf[name] = dataType
                descriptionOf[name] = args[1]
    members = dict((path, []) for path in classOf)
    for (call, args, kwargs) in entries:
        name = args[0] if call == 'DefDataAccess' else kwargs.get('pyName', '')
        if '.' not in name:
            continue
        (parent, member) = name.rsplit('.', 1)
        if parent not in members:
            continue
        memberWriter = DeclarationWriter()
        if call == 'DefDataAccess':
            memberWriter.DefDataAccess(member, args[1], dataType=kwargs.get('dataType', ''), isTopLevel=False,
                                       readOnly=kwargs.get('readOnly', False))
        else:
            memberKwargs = dict(kwargs, cClass=classOf[parent], pyName=member)
            memberWriter.DefPyFunctionAccess(**memberKwargs)
        members[parent].append(memberWriter.sPyi)
    stub = ''
    #the parts before the objects that hold them, so that a reader meets them in that order
    for path in sorted(classOf, key=lambda path: -path.count('.')):
        stub += 'class ' + classOf[path] + ':\n'
        stub += '    """' + descriptionOf[path].replace(chr(34)*3, chr(39)*3) + '"""\n'
        stub += ''.join(members[path]) if members[path] else '    ...\n'
    for path in classOf:
        if '.' not in path:
            stub += path + ':' + classOf[path] + '\n'
            stub += '"""' + descriptionOf[path].replace(chr(34)*3, chr(39)*3) + '"""\n'
    return stub


referenceTag = ' (`returns a reference`)'
scalarTypes = ['bool', 'int', 'float', 'str']


def MarkReferences(name, args, kwargs, referencedMember):
    """WHAT IS A REFERENCE, SAID BY THE BINDING ITSELF (#1061): a function bound with py::return_value_policy::reference,
    and a member bound by def_readwrite with it, get the tag `returns a reference` in their description, so that the
    documentation cannot drift from the binding; a member of a scalar type is copied by Python anyway and gets none"""
    if name == 'DefPyFunctionAccess' and 'return_value_policy::reference' in kwargs.get('options', ''):
        if 'description' in kwargs:
            kwargs = dict(kwargs, description=kwargs['description'] + referenceTag)
        else:
            args = args[:3] + (args[3] + referenceTag,) + tuple(args[4:])
    elif (name == 'DefDataAccess' and referencedMember is not None and args[0].split('.')[-1] == referencedMember
          and kwargs.get('dataType', '') not in scalarTypes):
        args = (args[0], args[1] + referenceTag) + tuple(args[2:])
    return (args, kwargs)


class Replay:
    """replays recorded declaration calls into a DeclarationWriter; keeps the stub sections"""
    def __init__(self):
        self.stubSections = ''  #closed stub sections, latest first
        self.savedCpp = None
        self.savedStub = None
        self.noStubEntries = None   #the declarations of a NoStub section, see ModuleObjectStubs
        self.submodulesHook = None  #called by CSubmodulesHere with the writer

    def __call__(self, calls, writer):
        referencedMember = None #the member a CppCode just bound with return_value_policy::reference
        for name, args, kwargs in calls:
            (args, kwargs) = MarkReferences(name, args, kwargs, referencedMember)
            referencedMember = None
            if self.noStubEntries is not None and name in ['DefDataAccess', 'DefPyFunctionAccess']:
                self.noStubEntries.append((name, args, kwargs))
            if name in declarationCalls:
                getattr(writer, name)(*args, **kwargs)
            elif name == 'CppCode':
                writer.sPy += args[0]
                match = re.search(r'\.def_readwrite\("(\w+)".*return_value_policy::reference', args[0])
                if match:
                    referencedMember = match.group(1)
            elif name == 'StubCode':
                writer.sPyi += args[0]
            elif name == 'ResetMarkdown':
                writer.sMarkdown = ''   #the chapter title lives in the index
            elif name == 'BeginCppWrittenByHand':
                assert self.savedCpp is None, 'BeginCppWrittenByHand is not closed'
                self.savedCpp = writer.sPy
            elif name == 'EndCppWrittenByHand':
                writer.sPy = self.savedCpp
                self.savedCpp = None
            elif name == 'BeginNoStub':
                assert self.savedStub is None, 'BeginNoStub is not closed'
                self.savedStub = writer.sPyi
                self.noStubEntries = []
            elif name == 'EndNoStub':
                writer.sPyi = self.savedStub + ModuleObjectStubs(self.noStubEntries)
                self.savedStub = None
                self.noStubEntries = None
            elif name == 'EndStubSection':
                self.stubSections = writer.sPyi + self.stubSections
                writer.sPyi = ''
            elif name == 'CppFinishClass':
                writerFinish = DeclarationWriter()
                writerFinish.DefPyFinishClass(args[0])
                writer.sPy += writerFinish.PyStr()
            elif name == 'CSubmodulesHere':
                self.submodulesHook(writer)
            elif name == 'ExtensionMarkdown':
                with open(paths.generatedDir+args[0]+'.md', 'r', encoding='utf8') as f:
                    writer.sMarkdown += '\n' + f.read()
            else:
                raise ValueError('unknown declaration call ' + name)
        assert self.savedCpp is None and self.savedStub is None, 'unbalanced Begin/End declaration calls'


#the file names are those of the RST split (CreateNewRSTfile); a page needs a title of its own,
#because the LaTeX sections inside it start one level below the chapter
markdownPageTitles = {
    'GeneralInformation': 'General information',
    'Exudyn': 'Exudyn module functions',
    'SystemContainer': 'SystemContainer',
    'Renderer': 'Renderer',
    'MainSystem': 'MainSystem',
    'SystemData': 'SystemData',
    'Symbolic': 'Symbolic',
    'GeneralContact': 'GeneralContact',
    'DataStructures': 'Data structures',
    'TypeDefinitions': 'Type definitions',
    'EnvironmentVariables': 'Environment variables',
    }


def WriteMarkdownPages(writer):
    """docs/generated/cInterface/: one page per file of the RST split, plus the chapter index
    which carries the chapter label"""
    markdownDir = os.path.join(paths.repositoryRoot, 'docs', 'generated', 'cInterface')
    os.makedirs(markdownDir, exist_ok=True)

    def Banner(title, label=''):
        return ('<!-- GENERATED by tools/generators/pybindEmitter.py from definitions/ '
                '- do not edit -->\n'
                + (label + '\n' if label != '' else '')
                + '# ' + title + '\n\n')

    indexText = ('<!-- GENERATED by tools/generators/pybindEmitter.py from definitions/ '
                 '- do not edit -->\n'
                 + MarkdownLabel('sec:pcpp:command:interface') + '\n'
                 '# Python-C++ interface\n\n'
                 '```{toctree}\n:maxdepth: 3\n\n')

    written = 0
    for (name, text) in writer.markdownPages:
        if text.strip() == '':
            continue
        #a page that opens with its own name says it twice and spends a heading level on it
        #(#2660)
        title = markdownPageTitles.get(name, name)
        (label, body) = DropRepeatedTitle(text.strip(), title)
        page = NotebookOrigins(NormalizeHeadings(Banner(title, label) + body)) + '\n'
        with io.open(os.path.join(markdownDir, name + '.md'), 'w', encoding='utf8',
                     newline='\n') as file:
            file.write(page)
        written += 1
        indexText += name + '\n'

    with io.open(os.path.join(markdownDir, 'cInterfaceIndex.md'), 'w', encoding='utf8',
                 newline='\n') as file:
        file.write(indexText + '```\n')

    print('pybindEmitter: ' + str(written + 1) + ' Markdown file(s) written')


def Declarations(name):
    return importlib.import_module(name)


def main():
    localListFunctionNames.clear()
    localListClassNames.clear()
    localListEnumNames.clear()
    replay = Replay()

    #the chapter introduction; it goes before everything else, but the enums are replayed first
    writerMain = DeclarationWriter()
    replay(Declarations('pybindGeneralInformation').pb.calls, writerMain)

    #the OutputVariableType registrator owns the enum and writes its C++ header; enumEmitter writes EnumTypes.h
    outputVariableEmitter.EmitHeader()
    enumEmitter.EmitHeader()

    writer = DeclarationWriter()
    replay(Declarations('pybindEnums').pb.calls, writer)
    sStubEnums = writer.sPyi
    writer.sPyi = ''
    sMarkdownEnum = writer.sMarkdown #the enums are documented after the systemData section

    #now start the main page:
    writer.sMarkdown = ''
    writer.CreateNewPage('GeneralInformation')
    writer.sMarkdown = writerMain.sMarkdown

    #the submodules cMath, cUtilities (#2958, #2960), replayed where pybindModule says CSubmodulesHere: their C++ bindings
    #go into the main file, each inside a block that binds into the compiled submodule exudyn._<name>, their documentation
    #becomes sections of the module page, their stubs a file each, for python/exudyn/<name>.pyi
    stubsOfSubmodules = {}
    def ReplaySubmodules(writer):
        for (submoduleName, definitionName) in cSubmodules:
            definition = Declarations(definitionName)
            replaySubmodule = Replay() #a state of its own: the module page is inside a BeginNoStub block
            replaySubmodule(definition.pb.calls, writer)
            writerSubmodule = DeclarationWriter()
            replaySubmodule(definition.module.calls, writerSubmodule)
            writer.sPy += writerSubmodule.sPy
            writer.sMarkdown += '\n' + writerSubmodule.sMarkdown #a paragraph of its own
            #one signature per function: the @overload the writer adds for the module functions of symbolic (float and
            #symbolic.Real) would be a single overload here, which a type checker refuses
            stubsOfSubmodules[submoduleName] = writerSubmodule.sPyi.replace('@overload\n', '')
    replay.submodulesHook = ReplaySubmodules

    for name in ['pybindModule', 'pybindSystemContainer', 'pybindRenderer', 'pybindMainSystem', 'pybindSystemData']:
        replay(Declarations(name).pb.calls, writer)

    #the symbolic submodule: its stubs go into a separate file, its documentation into writer
    symbolic = Declarations('pybindSymbolic')
    replay(symbolic.pb.calls, writer)
    writerSym = DeclarationWriter()
    replay(symbolic.symbolicModule.calls, writerSym)
    writerSym.sPyi = writerSym.sPyi.replace('symbolic.','')
    writer.sMarkdown += writerSym.sMarkdown

    for name in ['pybindGeneralContact', 'pybindDataStructures']:
        replay(Declarations(name).pb.calls, writer)
    sStubEnums += writer.sPyi #the type definitions are needed earlier and go into enums file
    savedPyi = replay.stubSections

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #now finalize files:
    writer.CreateNewPage('TypeDefinitions')
    writer.sMarkdown += sMarkdownEnum
    #the environment variables close the chapter; their declarations only write documentation
    replay(Declarations('pybindEnvironment').pb.calls, writer)
    writer.CreateNewPage('') #this finalizes the list

    directoryString = paths.autogeneratedDir
    pybindFile = directoryString + 'pybind_manual_classes.h'

    #write only if content changed, ignoring the volatile 'last modified' date line;
    #otherwise the file shows up as modified on every run and hides real generator drift
    sPybind = ''
    sPybind += '// AUTO:  ++++++++++++++++++++++\n'
    sPybind += '// AUTO:  pybind11 manual module includes; generated by Johannes Gerstmayr\n'
    sPybind += '// AUTO:  last modified = '+ GetDateStr() + '\n'
    sPybind += '// AUTO:  ++++++++++++++++++++++\n'
    sPybind += writer.PyStr()
    WriteTextIfDifferent(pybindFile, sPybind, True)

    #only the Markdown is written

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #MARKDOWN: the same pages, in docs/generated/ where emitter output
    #belongs.
    WriteMarkdownPages(writer)

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #stub file .pyi (will be merged with general file)
    file=io.open(paths.generatedDir+'stubAutoBindings.pyi','w',encoding='utf8')  #clear file by one write access
    file.write(savedPyi)
    #file.write(writer.sPyi)
    file.close()

    #stub file symbolic.pyi (will be merged with general file)
    file=io.open(paths.generatedDir+'stubSymbolic.pyi','w',encoding='utf8')  #clear file by one write access
    file.write(writerSym.sPyi)
    #file.write(writer.sPyi)
    file.close()

    #stub files of exudyn.cMath, exudyn.cUtilities (#2958, #2960)
    for (submoduleName, stub) in stubsOfSubmodules.items():
        with io.open(paths.generatedDir + 'stub' + submoduleName[0].upper() + submoduleName[1:] + '.pyi', 'w',
                     encoding='utf8') as file:
            file.write(stub)

    file=io.open(paths.generatedDir+'stubEnums.pyi','w',encoding='utf8')  #clear file by one write access
    file.write(sStubEnums)
    file.close()

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #write function, class, ... names for conf.py

    sConfHelper = ''
    sConfHelper += '#this is a helper file to define additional keywords for examples\n'
    sConfHelper += '#Created: 2023-03-17, Johannes Gerstmayr\n\n'

    #some manual entries ...
    localListClassNames.append('SimulationSettings')
    localListFunctionNames.append('visualizationSettings') #in fact, it is a member
    localListFunctionNames.append('systemData') #in fact, it is a member
    localListFunctionNames.append('systemIsConsistent') #in fact, it is a member
    localListFunctionNames.append('interactiveMode') #in fact, it is a member

    #list of classes and enum classes:
    sConfHelper += 'listClassNames=['
    for s in localListClassNames:
        sConfHelper += "'" + s + "'" + ', '
    for s in localListEnumNames:
        sConfHelper += "'" + s + "'" + ', '
    sConfHelper += ']\n\n'

    sConfHelper += 'listFunctionNames=['
    for s in localListFunctionNames:
        sConfHelper += "'" + s + "'" + ', '
    sConfHelper += ']\n\n'


    with open(paths.generatedDir+'confHelper.py', 'w', encoding='utf8') as f:
        f.write(sConfHelper)



    return 0


if __name__ == '__main__':
    sys.exit(main())
